:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-linen-surface: #f2f1ed;
  --color-ink: #000000;
  --color-graphite-caption: #737373;
  --color-stone-hairline: #e5e5e5;
  --color-pebble-progress: #a3a3a3;
  --color-sunbeam-grain: #f2c46d;
  --color-cobalt-grain: #2f7cf6;
  --color-mint-grain: #3ed68a;

  /* Typography — Font Families */
  --font-bureau-serif: "bureauSerif", "Newsreader", "Source Serif 4", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-inter: "Inter", "Geist", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.333;
  --tracking-small: 0.01px;
  --text-caption: 14px;
  --leading-caption: 1.571;
  --tracking-caption: 0.14px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.429;
  --tracking-body-sm: -0.18px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-subheading: 20px;
  --leading-subheading: 1.4;
  --tracking-subheading: -0.3px;
  --text-heading-sm: 20px;
  --leading-heading-sm: 1;
  --tracking-heading-sm: -0.6px;
  --text-heading: 28px;
  --leading-heading: 1;
  --tracking-heading: -0.84px;
  --text-heading-lg: 40px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: -1.2px;
  --text-display: 72px;
  --leading-display: 1;
  --tracking-display: -2.16px;

  /* Typography — Weights */
  --font-weight-light: 200;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-28: 28px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-72: 72px;
  --spacing-80: 80px;
  --spacing-104: 104px;
  --spacing-112: 112px;
  --spacing-128: 128px;

  /* Layout */
  --layout-max-width: 1512px;
  --layout-section-gap: 112px;
  --layout-card-padding: 32px;
  --layout-element-gap: 16px;

  /* Border Radius */
  --radius-sm: 8px;
  --radius-lg: 24px;
  --radius-xl: 32px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-inputs: 9999px;
  --radius-tags: 9999px;
  --radius-avatars: 9999px;
  --radius-cards: 32px;
  --radius-images: 32px;
  --radius-alert-banners: 24px;
  --radius-small-elements: 8px;

  /* Shadows */
  --shadow-subtle: 0px 1px 2px 0px rgba(2, 6, 23, 0.05);
  --shadow-sm: inset 0px 0px 0px 1px #f2f1ed;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-linen-surface: #f2f1ed;
  --surface-ink: #000000;
}

